import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String s = sc.next();
    sc.close();

    char ini = s.charAt(0);
    if (ini != s.charAt(1)) {
        System.out.println(2);
    } else {
        for (int i = 2; i < s.length(); i++) {
            if (ini != s.charAt(i)) {
                System.out.println(i + 1);
                break;
            }
        }
    }
}
